-- Preserve original prose while linking first screen reference in each of 12 remaining guides.
-- Only apply to guides without existing links; later staff edits take precedence.
update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Every response to a ","type":"text"},{"text":"query","type":"text","marks":[{"type":"link","attrs":{"href":"/audience-listening"}}]},{"text":" is a submission, made up of one answer per question it asked.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Find a submission","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Open the query and select its ","type":"text"},{"text":"Submissions","type":"text","marks":[{"type":"bold"}]},{"text":" tab — the count in the tab label tells you how many there are.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select a participant''s name to open their submission.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Review one","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The left column shows the participant''s details, their consent and attribution choices, and a note field only your staff can see.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The right column lists every question in order, each with an outcome — answered, incomplete, skipped, or not asked (a question added after this participant responded).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"An answered question has an audio player, its duration and file size, and a link to download the original file.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Mark reviewed","type":"text","marks":[{"type":"bold"}]},{"text":", ","type":"text"},{"text":"Flag","type":"text","marks":[{"type":"bold"}]},{"text":", and ","type":"text"},{"text":"Reject","type":"text","marks":[{"type":"bold"}]},{"text":" apply to the whole submission, at the top of the page; the same actions are also available per answer, further down.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"“Incomplete” means the upload started but never finished — the audio may not exist. The screen says so plainly rather than showing a broken player.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"If a question''s wording has changed since this answer was recorded, the answer shows the wording as it was asked, alongside how it reads today.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Each answer has its own note field, separate from the submission-level one.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen link in existing instructions' where slug='audience-listening-review-submissions' and body::text not like '%"href"%';
update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"A ","type":"text"},{"text":"query","type":"text","marks":[{"type":"link","attrs":{"href":"/audience-listening"}}]},{"text":" is a public listening initiative: up to five ordered questions, published as its own page or embedded in a Grove article, with the answers coming back to you here.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Create a query","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"From the query list, select ","type":"text"},{"text":"New query","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Fill in an internal title (for your own list), a public title (what a listener sees), and a public introduction saying why you''re asking and what you''ll do with the answers. Select ","type":"text"},{"text":"Create query","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"You land on the new query''s Questions tab.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Add questions","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Fill in a question''s prompt, and optionally public guidance, internal context (staff-only), a maximum answer length, and whether it''s required.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select ","type":"text"},{"text":"Add question","type":"text","marks":[{"type":"bold"}]},{"text":". Repeat for up to five questions.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Reorder or duplicate a question with the buttons on its card, or remove one — before anyone has answered.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Configure settings","type":"text"}]},{"type":"paragraph","content":[{"text":"The Settings tab covers everything about how the query behaves, separate from its questions:","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Participant information","type":"text","marks":[{"type":"bold"}]},{"text":" — which details (name, city, email, phone, a free-text note) to ask for, each set to don''t ask, optional, or required. Asked once for the whole submission, never per question.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Consent and attribution","type":"text","marks":[{"type":"bold"}]},{"text":" — three separate questions that stay separate on the record: permission to be contacted, permission to be named, and the option to request anonymity. Permission to be contacted is not permission to be named, and asking for anonymity is neither. The consent terms text itself is required and is recorded with the submission at the moment it''s accepted.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Opens and closes dates","type":"text","marks":[{"type":"bold"}]},{"text":" — both optional; leaving them blank means the query opens as soon as you select ","type":"text"},{"text":"Open for responses","type":"text","marks":[{"type":"bold"}]},{"text":" and stays open until you close it. Someone already recording when a close date passes may still finish and submit.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Transcription","type":"text","marks":[{"type":"bold"}]},{"text":" — manual (send answers after reviewing them) or automatic (every answer is queued the moment it''s submitted, then sent in one click from the Submissions tab).","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Publish it","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"On the query''s header — visible from any tab — select ","type":"text"},{"text":"Open for responses","type":"text","marks":[{"type":"bold"}]},{"text":". Until then, the public link and embed code don''t work, even for someone who already has them.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Go to the Share tab for a ","type":"text"},{"text":"Copy link","type":"text","marks":[{"type":"bold"}]},{"text":" button for the standalone public page, and a ","type":"text"},{"text":"Copy embed code","type":"text","marks":[{"type":"bold"}]},{"text":" button for a ready-made Grove iframe snippet — paste it into a Grove Responsive Embed element unchanged. If you add or remove questions later, copy the embed code again.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select ","type":"text"},{"text":"Preview","type":"text","marks":[{"type":"bold"}]},{"text":" (always available, even on a draft) to walk through the query as a participant would — nothing is submitted.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Once a query has submissions, question wording stays editable, but removing or reordering questions is no longer offered — an answer keeps the exact wording it was asked under.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The header''s action changes with status: open queries offer ","type":"text"},{"text":"Close query","type":"text","marks":[{"type":"bold"}]},{"text":" (stops new responses; anyone already recording can still finish); closed ones offer ","type":"text"},{"text":"Open for responses","type":"text","marks":[{"type":"bold"}]},{"text":" or ","type":"text"},{"text":"Archive query","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A query can be deleted only before it has any submissions, from the Settings tab. Once a submission exists, archiving — which keeps every response, answer, and transcription link — is how you finish with it.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen link in existing instructions' where slug='audience-listening-create-and-publish' and body::text not like '%"href"%';
update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"A package is the usual recipe for a kind of work. When one ","type":"text"},{"text":"request","type":"text","marks":[{"type":"link","attrs":{"href":"/bookings/requests"}}]},{"text":" needs something different, use ","type":"text"},{"text":"Adjust scope","type":"text","marks":[{"type":"bold"}]},{"text":" on that line: change the hours, equipment or crew and say why. The package and the rate model are not changed, the request keeps a reference to the standard recipe and shows the difference, and the request carries a Scope adjusted badge.","type":"text"}]},{"type":"paragraph","content":[{"text":"An adjusted line is priced from its own cost. The package''s market floor and ceiling are scaled by the same change in cost, which is a judgment Finance should confirm. Reset the line to go back to the standard recipe.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Hours used","type":"text"}]},{"type":"paragraph","content":[{"text":"After the work is delivered, confirm the hours and equipment actually used. They feed the assumed-versus-observed view in the Term report and never change a price.","type":"text"}]}]}'::jsonb,version_note='Contextual screen link in existing instructions' where slug='bookings-adjust-scope' and body::text not like '%"href"%';
update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Once a ","type":"text"},{"text":"request","type":"text","marks":[{"type":"link","attrs":{"href":"/bookings/requests"}}]},{"text":" is delivered and production has confirmed the hours and equipment used, Finance settles it. The ","type":"text"},{"text":"Settlement","type":"text","marks":[{"type":"bold"}]},{"text":" panel on the request drafts itself: the amount is the approved estimate''s, with each direct expense replaced by what it actually cost, and the cost to WUWF is the confirmed hours and equipment at the rate card the request was priced on. The hours never change what the partner is charged; they change what the work cost WUWF.","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A university unit is recharged to its funding index. An outside partner is invoiced, with the assessment and margin shown on their own lines.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Type the actual cost of any direct expense, or leave it blank to settle it as estimated. Update the draft to recalculate from the hours confirmed now.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Post the entry in the university''s own system, then enter its journal entry number here and post the settlement. Posting settles the request, and a posted settlement is final.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"WUWF contributes the cost the partner''s payment does not cover, never less than zero. The Term report totals settled requests so actual cost can be read against the estimates.","type":"text"}]}]}'::jsonb,version_note='Contextual screen link in existing instructions' where slug='bookings-settlement' and body::text not like '%"href"%';
update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"A ","type":"text"},{"text":"rundown''s screen","type":"text","marks":[{"type":"link","attrs":{"href":"/log"}}]},{"text":" does double duty: build it ahead of time, then run the same screen live once you start the broadcast.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Generate and fill","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"On the Today screen, select ","type":"text"},{"text":"Generate","type":"text","marks":[{"type":"bold"}]},{"text":" next to a program that doesn''t have a rundown yet for that date.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Open it. Hover the thin line between items in a break to fill it — search the eligible content library, add today''s weather, or create a one-off live read right there.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Go live","type":"text"}]},{"type":"paragraph","content":[{"text":"Select ","type":"text"},{"text":"Start broadcast","type":"text","marks":[{"type":"bold"}]},{"text":" in the sidebar. The current break is highlighted, and the mid-broadcast controls appear on every unconfirmed item across the whole rundown.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"During the broadcast","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"On an underwriting credit, confirm it with ","type":"text"},{"text":"Yes, aired","type":"text","marks":[{"type":"bold"}]},{"text":" or ","type":"text"},{"text":"No — flag it","type":"text","marks":[{"type":"bold"}]},{"text":" (choosing a reason). Ordinary content has no aired/missed confirmation — only a credit carries that obligation.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Move any item with its ","type":"text"},{"text":"⋮","type":"text","marks":[{"type":"bold"}]},{"text":" menu, or drag it to a different break.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Wrap up","type":"text"}]},{"type":"paragraph","content":[{"text":"The sidebar''s Wrap-up panel lists anything unresolved. Optionally attest or mark items aired in bulk, then select ","type":"text"},{"text":"Submit rundown","type":"text","marks":[{"type":"bold"}]},{"text":" — a checkpoint, not a lock. A correction after submission works exactly the same as before it.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Aired, missed, and move actions are queued on your device and sent once you''re back online — a dropped connection doesn''t lose them.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Adding content to a break needs a live connection, since it''s a request to the server rather than a queued action.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen link in existing instructions' where slug='log-daily-rundown-and-console' and body::text not like '%"href"%';
update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"The ","type":"text"},{"text":"program log","type":"text","marks":[{"type":"link","attrs":{"href":"/log/import"}}]},{"text":" is the day''s schedule as the traffic system exports it, as a PDF. Importing it builds that day''s rundowns with each break and its credits already in place.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Start from Today","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"On the Today tab, choose the day, then select ","type":"text"},{"text":"Import program log","type":"text","marks":[{"type":"bold"}]},{"text":". If some programs have no rundown yet, the notice above the table links there too.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Choose the PDF and select ","type":"text"},{"text":"Preview import","type":"text","marks":[{"type":"bold"}]},{"text":". Reading the log can take a minute, and nothing is written yet.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Review the plan. If the log is dated a different day than the one you started from, a notice says so: rundowns are created for the log''s date.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Check the rows that could not be placed, any new underwriters or copy, and any library scripts that will change. Then select ","type":"text"},{"text":"Import","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"You land on Today for the log''s date, where the new rundowns are listed.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"If a rundown already exists","type":"text"}]},{"type":"paragraph","content":[{"text":"A program that already has a rundown for that date is skipped and named in the result. The import stays on its own page in that case so the reasons are easy to read, with a link back to Today.","type":"text"}]}]}'::jsonb,version_note='Contextual screen link in existing instructions' where slug='log-import-a-program-log' and body::text not like '%"href"%';
update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"The station identifies itself every hour, as close to the top of the hour as it can, at a natural break. The legal ID is pinned on each ","type":"text"},{"text":"clock''s page","type":"text","marks":[{"type":"link","attrs":{"href":"/log/programs"}}]},{"text":", the same way as any other pinned content, and goes into every rundown made from that clock.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Pin the station ID","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Open the program, then ","type":"text"},{"text":"Open clock","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select the slot that takes the legal ID, usually the last break before the top of the hour.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select ","type":"text"},{"text":"Pin content","type":"text","marks":[{"type":"bold"}]},{"text":" and choose the station ID. Leave the hour on ","type":"text"},{"text":"Every hour","type":"text","marks":[{"type":"bold"}]},{"text":" and no days checked, then select ","type":"text"},{"text":"Pin content","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"If an hour on the clock in effect has no legal ID, a warning at the top of the clock''s page says which.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"If no slot takes a legal ID yet, the warning says so. The program director marks the slot eligible for a legal ID first.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A new clock version starts without pins, so pin the ID again on the new version.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A pinned ID goes into rundowns made from then on. Rundowns already made keep what they have.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The program director or traffic can pin and remove the ID.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen link in existing instructions' where slug='log-station-ids' and body::text not like '%"href"%';
update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"A university unit or an outside organization asks WUWF for production work or airtime at ","type":"text"},{"text":"tools.wuwf.org/book","type":"text","marks":[{"type":"code"},{"type":"link","attrs":{"href":"https://tools.wuwf.org/book"}}]},{"text":", or through the same form embedded in a Grove page. No sign-in is needed and no rate appears on the form. Each submission lands on the Requests tab at the Request stage, marked as received from the public form, with the submitter''s unit named as the partner (an existing partner by the same name is reused) and the submitter as the contact.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"What the form asks","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Who is asking: a name, an email, a phone, the college, department, office or organization, and whether it is part of UWF.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"What is needed: production, airtime or both; a short title; for production, which of the offered services (recorded on the request as ","type":"text"},{"text":"Services asked for","type":"text","marks":[{"type":"bold"}]},{"text":" — production staff add the real estimate lines); a description.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"When and where: the event or recording dates, when the finished work is needed, and a location. The form books nothing; dates are checked and held when the estimate is sent.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"For airtime: airings a week, the length of each, and the first and last airing. When all three are given the request carries an airtime commitment, contributed by default, for staff to review against the term''s envelope.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Settings","type":"text"}]},{"type":"paragraph","content":[{"text":"From Requests, ","type":"text"},{"text":"Public form","type":"text","marks":[{"type":"bold"}]},{"text":" opens the form''s settings. The Director of Operations or the Executive Director decides whether the form is taking requests, edits the introduction, the confirmation shown after a request is sent and the copy shown while the form is closed, and lists the services the form offers, one a line. Everyone with access can read the settings and copy the public link or the Grove embed code; the preview beneath them shows the form as it is served.","type":"text"}]},{"type":"paragraph","content":[{"text":"A visitor may send at most three requests a day from one email address, and a form that was filled in faster than a person could is refused.","type":"text"}]}]}'::jsonb,version_note='Contextual screen link in existing instructions' where slug='bookings-intake' and body::text not like '%"href"%';
update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"The ","type":"text"},{"text":"Sources","type":"text","marks":[{"type":"link","attrs":{"href":"/log/sources"}}]},{"text":" tab holds the outside feeds On Air reads. It opens on one card per source, showing whether its saved data is current, when it was last updated, and what it holds. Select a card''s ","type":"text"},{"text":"Open","type":"text","marks":[{"type":"bold"}]},{"text":" button to go to that source''s page, and ","type":"text"},{"text":"← Sources","type":"text","marks":[{"type":"bold"}]},{"text":" to come back.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"What the cards say","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Up to date","type":"text","marks":[{"type":"bold"}]},{"text":": the saved data is inside its normal refresh window.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Stale","type":"text","marks":[{"type":"bold"}]},{"text":": the saved data is older than that, or the last refresh failed. What was saved is still shown.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Not fetched yet","type":"text","marks":[{"type":"bold"}]},{"text":": nothing has been read from this source so far.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Not configured","type":"text","marks":[{"type":"bold"}]},{"text":": the portal has no access set up for this source yet.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"NPR","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"On the NPR page, choose a program and a show date, then select ","type":"text"},{"text":"Switch","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The table lists each story''s estimated air time (marked with “~”, since NPR doesn''t supply exact times), title, teaser, and length.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select ","type":"text"},{"text":"Refresh","type":"text","marks":[{"type":"bold"}]},{"text":" to pull the latest episode data.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"The NPR card reports the most recently read episode. NPR is read one program and date at a time, so it is refreshed from the NPR page rather than the card.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Weather","type":"text"}]},{"type":"paragraph","content":[{"text":"The weather page shows the current forecast: any hazards, a short outlook, live-read and condensed text for on air, and the underlying details. Select ","type":"text"},{"text":"Refresh","type":"text","marks":[{"type":"bold"}]},{"text":" on the page or on the weather card to force an update.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sources refresh themselves when you open them and their data is past its window. Refresh is a manual option, not something you need to do routinely.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A fetch failure shows as a plain message, with whatever was last read still on screen. No page goes blank because of a temporary outage.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"NPR''s estimated times need a rundown to already exist for that program and date. Without one, the table has nothing to anchor its estimates to.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen link in existing instructions' where slug='log-npr-and-weather' and body::text not like '%"href"%';
update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Every hour is hosted unless it''s listed on ","type":"text"},{"text":"this page","type":"text","marks":[{"type":"link","attrs":{"href":"/log/automated-hours"}}]},{"text":". In automated hours no one is in the studio, so DAD plays that hour''s underwriting credits. Open it from ","type":"text"},{"text":"Schedule","type":"text","marks":[{"type":"bold"}]},{"text":", then ","type":"text"},{"text":"Automation","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Weekly hours","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Use ","type":"text"},{"text":"+ Weekly hours","type":"text","marks":[{"type":"bold"}]},{"text":" for the routine ones, such as overnights from 8:00 PM to 5:00 AM. Pick the days, the times, and the date they start.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"An end time at or before the start runs past midnight. The early-morning part belongs to the day the hours started, so Saturday 8:00 PM – 5:00 AM covers early Sunday.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Weekly hours can cover a whole program or just some of its hours. The ","type":"text"},{"text":"Programs in these hours","type":"text","marks":[{"type":"bold"}]},{"text":" column shows what''s on the air then.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"One-time changes","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Use ","type":"text"},{"text":"+ One-time change","type":"text","marks":[{"type":"bold"}]},{"text":" for a holiday, a host out, or a special. Choose ","type":"text"},{"text":"Automated","type":"text","marks":[{"type":"bold"}]},{"text":" to automate hours that are normally hosted, or ","type":"text"},{"text":"Live","type":"text","marks":[{"type":"bold"}]},{"text":" to host hours that are normally automated.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A one-time change wins over the weekly hours. One-time changes can''t overlap each other.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Midnight to midnight covers whole days: Thanksgiving is Thursday 12:00 AM until Friday 12:00 AM.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Week and month","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The week view draws each day''s automated hours over the programs on the air, with the hours closed to underwriting shown faintly behind them. Grey is weekly, dashed amber is automated once, and dashed blue is live once.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The month view shows each day''s automated hours. Pick a day to see its week.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A credit in automated hours needs copy with a DAD cut, since DAD plays it. A live read qualifies through its recorded version. Auto-fill leaves those breaks to copy that has one, and placing cut-less copy there is refused.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Only the program director can change automated hours. Nothing is deleted: removing hours or a change takes it off the schedule.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen link in existing instructions' where slug='log-automated-hours' and body::text not like '%"href"%';
update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"A credit needs approved ","type":"text"},{"text":"copy","type":"text","marks":[{"type":"link","attrs":{"href":"/underwriting/copy"}}]},{"text":" behind it before it can run anywhere.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Copy","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"On the contract''s Copy tab, select ","type":"text"},{"text":"+ New message","type":"text","marks":[{"type":"bold"}]},{"text":" or ","type":"text"},{"text":"Link existing…","type":"text","marks":[{"type":"bold"}]},{"text":" to attach a script. A draft message can be approved right from its card — only approved copy rotates or gets placed.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Copy shared across more than one contract shows which others use it, right on its edit card.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Rotation","type":"text"}]},{"type":"paragraph","content":[{"text":"Rotation is automatic: each contract cycles through its own linked messages in broadcast order, with nothing for staff to pick. An aired, frozen, or manager-overridden placement is a fixed point that rotation won''t move.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Rotation weights","type":"text"}]},{"type":"paragraph","content":[{"text":"By default every message on a contract airs equally often. When an order asks for one message to air more than another, open ","type":"text"},{"text":"Rotation weight…","type":"text","marks":[{"type":"bold"}]},{"text":" from the message''s menu and set a whole number from 1 to 20.","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Messages rotate in proportion to their weights: a weight of 2 against 1 airs the first twice as often, spread through the run rather than in a block.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Weights compare messages that rotate together: the contract''s general messages, or the messages dedicated to one line. Only approved messages count.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The card reads ","type":"text"},{"text":"airs 2 of every 3 spots","type":"text","marks":[{"type":"bold"}]},{"text":" once the weights differ. Aired credits count toward the ratio, and changing a weight re-sequences only credits that have not aired.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A weight belongs to the message on this contract; the same message on another order keeps its own.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"A message for one line","type":"text"}]},{"type":"paragraph","content":[{"text":"Some orders give a message to one line rather than to the whole contract — for example, “For Carpool: #1” and “For Total Program: #2”. When linking the message, choose the line under ","type":"text"},{"text":"Use on","type":"text","marks":[{"type":"bold"}]},{"text":", or use ","type":"text"},{"text":"Use on one line only…","type":"text","marks":[{"type":"bold"}]},{"text":" from a linked message''s menu.","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A message dedicated to a line airs only on that line.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"That line then airs only its own messages. If it has more than one, they rotate among themselves.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Every other line keeps rotating the contract''s other messages, as before.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"If a revision replaces the line, the message''s card shows ","type":"text"},{"text":"Line replaced — set it again","type":"text","marks":[{"type":"bold"}]},{"text":"; choose the new line.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Placing a credit","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Manually, from a schedule line''s ","type":"text"},{"text":"Place a credit","type":"text","marks":[{"type":"bold"}]},{"text":" link: pick an open break (grouped by period), confirm or change the suggested message (already the next one in rotation), and select ","type":"text"},{"text":"Place credit","type":"text","marks":[{"type":"bold"}]},{"text":". Only messages that may air on that line are offered.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Or let auto-fill do it: ","type":"text"},{"text":"Auto-fill this line","type":"text","marks":[{"type":"bold"}]},{"text":" from a line''s own menu, ","type":"text"},{"text":"Auto-fill this contract","type":"text","marks":[{"type":"bold"}]},{"text":" for every line on one contract, or ","type":"text"},{"text":"Auto-fill everything","type":"text","marks":[{"type":"bold"}]},{"text":" for every active contract — the same placement path either way, just run in a loop.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A same-underwriter or same-industry adjacency warning is advisory on the manual placement form — it''s shown, never blocked.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Auto-fill generates the rundowns it needs as it goes, so a fresh contract can be filled for its whole campaign in one click even before a rundown for those dates exists yet.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen link in existing instructions' where slug='underwriting-copy-and-placement' and body::text not like '%"href"%';
update public.rc_articles set body='{"type":"doc","content":[{"type":"paragraph","content":[{"text":"Every ","type":"text"},{"text":"message","type":"text","marks":[{"type":"link","attrs":{"href":"/underwriting/copy"}}]},{"text":" on file has a DAD cut: the number DAD plays it from. A recorded spot plays its recording. A live read is read by the host when someone is on air, and DAD plays its recorded version in hours with no host.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"New recording","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A new message gets the next free cut when you save it, in the form ","type":"text"},{"text":"00548A","type":"text","marks":[{"type":"bold"}]},{"text":". Record the message into DAD under that number.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Messages that were on file before cuts existed kept their old number where only one current message used it, so Loyalty Credit Union''s copy 1 is ","type":"text"},{"text":"00013A","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"To use another number, choose ","type":"text"},{"text":"Use a different cut","type":"text","marks":[{"type":"bold"}]},{"text":" on the copy''s edit page. A cut belongs to one message, so a number already in use is refused.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Recorded in DAD","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A new cut isn''t in DAD until someone records the message under it. The copy page shows ","type":"text"},{"text":"To record","type":"text","marks":[{"type":"bold"}]},{"text":" until production marks it with ","type":"text"},{"text":"Mark recorded","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The ","type":"text"},{"text":"To record","type":"text","marks":[{"type":"bold"}]},{"text":" filter in the copy library, and the dashboard''s ","type":"text"},{"text":"To record in DAD","type":"text","marks":[{"type":"bold"}]},{"text":" tile, list every message that can still air and isn''t recorded. Production can mark each one from that list.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Changing a message''s cut, or the wording of a message under a new cut, clears the mark, since the recording no longer matches.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A message that plays an existing DAD spot is already recorded.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The DAD log can''t be released while a credit in automated hours isn''t recorded.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Existing DAD spot","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Some copy asks the host to play a spot that''s already in DAD, such as a Learning Minute in the PPA group. Choose ","type":"text"},{"text":"Existing DAD spot","type":"text","marks":[{"type":"bold"}]},{"text":" and search DAD''s library by cut number or title.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Copy like this starts without a cut. It shows ","type":"text"},{"text":"Pick a DAD spot","type":"text","marks":[{"type":"bold"}]},{"text":" in the copy library, and the ","type":"text"},{"text":"Needs a DAD cut","type":"text","marks":[{"type":"bold"}]},{"text":" filter lists every message still waiting.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The copy page''s ","type":"text"},{"text":"Copy","type":"text","marks":[{"type":"bold"}]},{"text":" button puts the cut on the clipboard for pasting into DAD.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"On the rundown, a recorded spot shows the cut the host fires. A live read shows no cut.","type":"text"}]}]}]}]}'::jsonb,version_note='Contextual screen link in existing instructions' where slug='underwriting-copy-in-dad' and body::text not like '%"href"%';
